from itertools import permutations

def is_costas_array(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            if (dr, dc) in vectors:
                return False
            vectors.add((dr, dc))
    return True

# Try to find a Costas array of order 8
# This might be slow with brute force, let's try a smarter approach
