# Actually, let's use a backtracking approach which is more efficient
def find_costas_array(n):
    def backtrack(col, perm, vectors):
        if col == n:
            return perm[:]

        for row in range(n):
            if row in perm:
                continue

            # Check if adding this mark creates any duplicate vectors
            valid = True
            new_vectors = []
            for prev_col in range(col):
                prev_row = perm[prev_col]
                dr = row - prev_row
                dc = col - prev_col
                if (dr, dc) in vectors:
                    valid = False
                    break
                new_vectors.append((dr, dc))

            if valid:
                # Add new vectors
                for v in new_vectors:
                    vectors.add(v)
                perm.append(row)

                result = backtrack(col + 1, perm, vectors)
                if result is not None:
                    return result

                # Backtrack
                perm.pop()
                for v in new_vectors:
                    vectors.remove(v)

        return None

    return backtrack(0, [], set())

result = find_costas_array(8)
